import { useState, type FormEvent, type ChangeEvent } from 'react';
import { Plus, Trash2, Upload, Building2, Link2, Eye, EyeOff, Image as ImageIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Image } from '@/components/ui/image';
import { useClientLogos, type IClientLogo } from '@/hooks/useClientLogos';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import {
  extractBase64FromDataUrl,
  isLocalBase64Image,
} from '@/hooks/useGithubSync';

interface LogoForm {
  name: string;
  image: string;
  url: string;
}

export default function AdminClientLogosPage() {
  const { adminT } = useI18n();
  const { logos, showOnHomepage, updateShowOnHomepage, addLogo, updateLogo, deleteLogo } =
    useClientLogos();
  const { markDirty, syncModule, syncJsonFile, syncBase64Image, getStatus } = useSyncService();
  const syncStatus = getStatus('clientLogos');

  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<LogoForm>({ name: '', image: '', url: '' });
  const [uploading, setUploading] = useState(false);

  const handleAdd = () => {
    setEditingId(null);
    setForm({ name: '', image: '', url: '' });
    setDialogOpen(true);
  };

  const handleEdit = (logo: IClientLogo) => {
    setEditingId(logo.id);
    setForm({ name: logo.name, image: logo.image, url: logo.url });
    setDialogOpen(true);
  };

  const handleDelete = (id: string) => {
    if (!window.confirm(adminT('admin.confirmDelete'))) return;
    deleteLogo(id);
    toast.success('Logo deleted');
    markDirty('clientLogos');
  };

  const handleImageChange = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }

    setUploading(true);
    try {
      const dataUrl = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => reject(new Error('Failed to read file'));
        reader.readAsDataURL(file);
      });
      setForm((prev) => ({ ...prev, image: dataUrl }));
    } catch (err) {
      toast.error('Failed to upload image');
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!form.name.trim()) {
      toast.error('Please enter customer name');
      return;
    }
    if (!form.image) {
      toast.error('Please upload a logo image');
      return;
    }

    try {
      if (editingId) {
        updateLogo(editingId, {
          name: form.name.trim(),
          image: form.image,
          url: form.url.trim(),
        });
        toast.success('Logo updated');
      } else {
        addLogo({
          name: form.name.trim(),
          image: form.image,
          url: form.url.trim(),
        });
        toast.success('Logo added');
      }
      markDirty('clientLogos');
      setDialogOpen(false);
    } catch (err) {
      toast.error('Failed to save logo');
    }
  };

  const handleToggleShow = async (checked: boolean) => {
    updateShowOnHomepage(checked);
    markDirty('clientLogos');
  };

  const handleSync = async () => {
    await syncModule('clientLogos', 'Client Logos', async (config) => {
      // 1. 同步所有 base64 图片到 GitHub
      const uploadedLogos: IClientLogo[] = [];
      for (const logo of logos) {
        if (isLocalBase64Image(logo.image)) {
          const timestamp = Date.now();
          const random = Math.random().toString(36).slice(2, 8);
          const ext = 'png';
          const targetPath = `images/client-logos/${timestamp}_${random}.${ext}`;
          await syncBase64Image(config, logo.image, targetPath, `Upload client logo: ${logo.name}`);
          uploadedLogos.push({
            ...logo,
            image: `./${targetPath}`,
          });
        } else {
          uploadedLogos.push(logo);
        }
      }

      // 2. 同步配置 JSON
      const payload = {
        showOnHomepage,
        logos: uploadedLogos,
        updatedAt: Date.now(),
      };
      await syncJsonFile(config, 'data/client-logos.json', payload, 'Update client logos data');
    });
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb items={[{ label: adminT('admin.dashboard'), href: '/admin/dashboard' }, { label: 'Client Logos' }]} />

      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-bold text-foreground">Client Logos</h1>
            <SyncStatusBadge status={syncStatus} />
            <Button
              variant="outline"
              size="sm"
              onClick={handleSync}
              disabled={syncStatus === 'syncing'}
              className="text-xs h-9"
            >
              <Upload className="size-3.5 mr-1.5" />
              Sync to GitHub
            </Button>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            Manage customer/partner logos displayed on the homepage
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 px-3 py-2 bg-muted/50 rounded-md">
            <Switch
              id="show-on-homepage"
              checked={showOnHomepage}
              onCheckedChange={handleToggleShow}
            />
            <Label htmlFor="show-on-homepage" className="text-sm cursor-pointer">
              {showOnHomepage ? <Eye className="size-4 inline mr-1" /> : <EyeOff className="size-4 inline mr-1" />}
              Show on Homepage
            </Label>
          </div>
          <Button onClick={handleAdd} className="gap-2">
            <Plus className="size-4" />
            Add Logo
          </Button>
        </div>
      </div>

      {/* Logo Grid */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <Building2 className="size-5 text-primary" />
            Logo List
            <span className="ml-2 text-sm font-normal text-muted-foreground">
              ({logos.length} logos)
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {logos.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <ImageIcon className="size-12 mx-auto mb-3 opacity-30" />
              <p>No logos yet. Click "Add Logo" to add the first one.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {logos.map((logo) => (
                <div
                  key={logo.id}
                  className="group relative border border-border rounded-md p-4 bg-card hover:border-primary/50 transition-colors flex flex-col items-center gap-2"
                >
                  <div className="w-full h-16 flex items-center justify-center bg-muted/30 rounded overflow-hidden">
                    {logo.image ? (
                      <Image
                        src={logo.image}
                        alt={logo.name}
                        width={120}
                        height={64}
                        className="max-w-full max-h-full object-contain"
                      />
                    ) : (
                      <ImageIcon className="size-8 text-muted-foreground/50" />
                    )}
                  </div>
                  <div className="text-sm font-medium text-foreground truncate w-full text-center">
                    {logo.name}
                  </div>
                  {logo.url && (
                    <div className="text-xs text-muted-foreground truncate w-full text-center flex items-center justify-center gap-1">
                      <Link2 className="size-3" />
                      <span className="truncate">{logo.url.replace(/^https?:\/\//, '')}</span>
                    </div>
                  )}
                  <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                    <Button
                      variant="secondary"
                      size="icon"
                      className="h-7 w-7"
                      onClick={() => handleEdit(logo)}
                      title="Edit"
                    >
                      <Plus className="size-3" />
                    </Button>
                    <Button
                      variant="destructive"
                      size="icon"
                      className="h-7 w-7"
                      onClick={() => handleDelete(logo.id)}
                      title="Delete"
                    >
                      <Trash2 className="size-3" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editingId ? 'Edit Logo' : 'Add Logo'}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="logo-name">Customer / Partner Name</Label>
              <Input
                id="logo-name"
                value={form.name}
                onChange={(e) => setForm((prev) => ({ ...prev, name: e.target.value }))}
                placeholder="e.g. Acme Corp"
                required
              />
            </div>

            <div className="space-y-2">
              <Label>Logo Image</Label>
              <div className="border border-border rounded-md p-4 bg-muted/30">
                {form.image ? (
                  <div className="flex items-center justify-center h-24 mb-3">
                    <Image
                      src={form.image}
                      alt="Preview"
                      width={160}
                      height={80}
                      className="max-w-full max-h-full object-contain"
                    />
                  </div>
                ) : (
                  <div className="flex items-center justify-center h-24 mb-3 border border-dashed border-border rounded">
                    <ImageIcon className="size-8 text-muted-foreground/50" />
                  </div>
                )}
                <Input
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={handleImageChange}
                  disabled={uploading}
                  className="text-sm"
                />
                <p className="text-xs text-muted-foreground mt-2">
                  Recommended: PNG with transparent background, max 2MB
                </p>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="logo-url">Website URL (optional)</Label>
              <Input
                id="logo-url"
                type="url"
                value={form.url}
                onChange={(e) => setForm((prev) => ({ ...prev, url: e.target.value }))}
                placeholder="https://example.com"
              />
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="secondary"
                onClick={() => setDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={uploading}>
                {editingId ? 'Save Changes' : 'Add Logo'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
